cssScreen:
.pv *{box-sizing:border-box}
.mono{font-family:'JetBrains Mono',ui-monospace,monospace;font-size:12px}
.nd{position:absolute;top:6px;right:7px;width:8px;height:8px;border-radius:9px;background:var(--color-fg-error-primary);border:2px solid var(--color-bg-primary)}
.av{width:32px;height:32px;border-radius:99px;background:var(--color-accent-bg);color:var(--color-accent-fg);display:grid;place-items:center;font:600 12px Inter,system-ui,sans-serif;flex:none}
.chip{display:inline-block;font:500 12px/18px Inter,system-ui,sans-serif;padding:1px 8px;border-radius:999px;white-space:nowrap}
.chip.ok{background:var(--color-utility-green-50);color:var(--color-utility-green-700)}
.chip.warn{background:var(--color-utility-yellow-50);color:var(--color-utility-yellow-700)}
.chip.info{background:var(--color-utility-blue-50);color:var(--color-utility-blue-700)}
.app{display:flex;height:800px;width:100%;position:relative;overflow:hidden;background:var(--color-bg-primary)}
.s2 .dot{flex:none;padding:0 4px}
.mn{flex:1;min-width:0;display:flex;flex-direction:column}
.tb{height:56px;flex:none;border-bottom:1px solid var(--color-border-secondary);display:flex;align-items:center;gap:12px;padding:0 24px}
.sp{flex:1}
.tse{display:flex;align-items:center;gap:8px;width:260px;height:36px;border:1px solid var(--color-border-input);border-radius:8px;padding:0 10px;color:var(--color-text-tertiary);font-size:14px}
.tse kbd{margin-left:auto;font:500 12px Inter,system-ui,sans-serif;border:1px solid var(--color-border-secondary);border-radius:4px;padding:0 4px}
.ct{flex:1;overflow:hidden;padding:24px;position:relative}
.ph1{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:20px}
.pv h1{font:600 24px/32px Inter,system-ui,sans-serif;margin:0}
.pv h2{font:600 24px/32px Inter,system-ui,sans-serif;margin:0}
.sub{margin:2px 0 0;color:var(--color-text-tertiary);display:flex;gap:4px}
.sub>span{white-space:nowrap}
.tbl{border:1px solid var(--color-border-secondary);border-radius:12px;overflow:hidden}
.pv table{width:100%;border-collapse:collapse}
.pv td,.pv th{padding:12px 16px;border-bottom:1px solid var(--color-border-secondary);text-align:left;font-size:14px}
.pv tr:last-child td{border-bottom:0}
.pv th{color:var(--color-text-tertiary);font:500 12px/18px Inter,system-ui,sans-serif;background:var(--color-bg-secondary)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:20px}
.kpi{border:1px solid var(--color-border-secondary);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:4px;color:var(--color-text-tertiary)}
.kpi b{font:600 28px/36px Inter,system-ui,sans-serif;color:var(--color-text-primary)}
.form{max-width:var(--width-md);margin:0 auto;display:flex;flex-direction:column;gap:6px}
.card{border:1px solid var(--color-border-secondary);border-radius:12px;padding:20px;display:flex;flex-direction:column;gap:16px;margin-top:14px}
.fl{display:flex;flex-direction:column;gap:6px;font:500 14px Inter,system-ui,sans-serif;color:var(--color-text-secondary)}
.in{height:40px;border:1px solid var(--color-border-input);border-radius:8px;padding:0 12px;display:flex;align-items:center;color:var(--color-text-primary);font-weight:400}
.phone{width:393px;height:800px;position:relative;overflow:hidden;display:flex;flex-direction:column;background:var(--color-bg-primary);margin:0 auto}
.mst{height:44px;flex:none;display:flex;justify-content:space-between;align-items:center;padding:0 24px;font:600 14px Inter,system-ui,sans-serif}
.mh1{display:flex;align-items:center;gap:12px;padding:8px 16px}
.hi{display:flex;flex-direction:column;flex:1;line-height:22px}
.hi span{color:var(--color-text-tertiary);font-size:14px}
.hi b{font:600 18px/26px Inter,system-ui,sans-serif}
.mib{width:44px;height:44px;display:grid;place-items:center;border-radius:var(--radius-control);position:relative;color:var(--color-text-secondary)}
.mib .nd{top:10px;right:11px}
.mpx{padding:4px 16px 8px}
.msc{display:flex;align-items:center;gap:12px;width:100%;padding:10px 12px;border:1px solid var(--color-border-secondary)!important;border-radius:14px;min-height:60px;background:var(--color-bg-primary)}
.mbar{height:52px;flex:none;display:flex;align-items:center;gap:4px;padding:0 6px}
.mbar b{font:600 18px/28px Inter,system-ui,sans-serif;padding-left:4px}
.mctx{display:flex;align-items:center;gap:8px;padding:0 16px 10px;font:500 12px Inter,system-ui,sans-serif;color:var(--color-text-secondary);min-width:0}
.mctx.in{padding:6px 10px;margin-top:6px;border:1px solid var(--color-border-input)!important;border-radius:var(--radius-control);height:32px;max-width:100%}
.mtt{padding:0 16px 12px}
.msc-body{flex:1;overflow:hidden;position:relative}
.mpad{padding:8px 16px;display:flex;flex-direction:column;gap:10px}
.sect{font:600 14px/20px Inter,system-ui,sans-serif;margin-top:6px}
.sgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px 8px}
.sg{display:flex;flex-direction:column;align-items:center;gap:6px;font:500 12px/16px Inter,system-ui,sans-serif;text-align:center;color:var(--color-text-secondary)}
.sgi{width:52px;height:52px;border-radius:var(--radius-inner);background:var(--color-bg-tertiary);display:grid;place-items:center;color:var(--color-text-primary);position:relative}
.sgb{position:absolute;top:-4px;right:-6px;font:600 11px/18px Inter,system-ui,sans-serif;font-style:normal;background:var(--color-bg-error-solid);color:var(--color-text-white);border-radius:99px;padding:0 6px}
.mlist{border-top:1px solid var(--color-border-secondary)}
.mrow{display:grid;grid-template-columns:1fr auto;gap:2px 8px;padding:14px 16px;border-bottom:1px solid var(--color-border-secondary);align-items:center}
.mpad .mlist{border:1px solid var(--color-border-secondary);border-radius:var(--radius-card);overflow:hidden}
.mpad .mrow:last-child{border-bottom:0}
.mrow .b{font:600 14px/20px Inter,system-ui,sans-serif}
.mrow .sub{grid-column:1;font-size:12px;color:var(--color-text-tertiary)}
.mtabs{height:64px;flex:none;border-top:1px solid var(--color-border-secondary);display:grid;grid-template-columns:repeat(4,1fr);background:var(--color-bg-primary)}
.mtabs.five{grid-template-columns:repeat(5,1fr)}
.mtab{display:grid;place-items:center;color:var(--color-text-tertiary)}
.mfoot{padding:12px 16px 24px;border-top:1px solid var(--color-border-secondary)}
.cta{width:100%;height:52px;border-radius:var(--radius-control)!important;background:var(--color-action-primary)!important;color:var(--color-text-inverse)!important;font:600 16px Inter,system-ui,sans-serif!important;text-align:center!important}
.mscrim{position:absolute;inset:0;background:var(--color-bg-overlay);backdrop-filter:blur(var(--backdrop-blur-lg));z-index:20}
.sheet{position:absolute;left:0;right:0;bottom:0;z-index:30;background:var(--color-bg-primary);border-radius:var(--radius-overlay) var(--radius-overlay) 0 0;max-height:86%;display:flex;flex-direction:column}
.hdl{display:block;width:36px;height:4px;border-radius:9px;background:var(--color-bg-quaternary);margin:8px auto 0}
.shh{display:flex;justify-content:space-between;align-items:center;padding:10px 16px 6px;font:600 18px/26px Inter,system-ui,sans-serif}
.shb{overflow:hidden;padding:0 8px;flex:1}
.shf{padding:12px 16px 24px;border-top:1px solid var(--color-border-secondary)}
.drw{position:absolute;left:0;top:0;bottom:0;width:316px;z-index:30;background:var(--color-bg-primary_alt);padding:52px 12px 12px;display:flex;flex-direction:column;gap:8px;border:1px solid var(--shadow-xl-border);box-shadow:var(--shadow-xl)}
.mnv{display:flex;flex-direction:column;overflow:hidden}
.mit{display:flex;align-items:center;gap:12px;min-height:48px;padding:0 12px;border-radius:10px;font:500 14px/20px Inter,system-ui,sans-serif;color:var(--color-text-secondary)}
.mmenu{position:absolute;left:0;right:0;top:44px;bottom:64px;z-index:15;background:var(--color-bg-primary);display:flex;flex-direction:column;padding-bottom:8px}
.mmenu .mnv{padding:0 4px}
.mfull{position:absolute;inset:0;z-index:30;background:var(--color-bg-primary);display:flex;flex-direction:column;padding-top:44px}
.mctx .dot{padding:0 4px;flex:none}
.ascr{overflow:hidden;padding-bottom:12px}
.apf{display:flex;align-items:center;gap:12px;padding:4px 16px 8px}
.apf .hi span{font-size:12px}
.sect2{font:600 12px/16px Inter,system-ui,sans-serif;color:var(--color-text-tertiary);padding:14px 16px 6px}
.mpx0{padding:0 16px}
.mnv.acc{padding:0 4px}
.agrp{margin:0 16px;border:1px solid var(--color-border-secondary);border-radius:var(--radius-card);overflow:hidden}
.arow{display:flex;align-items:center;gap:12px;min-height:52px;padding:0 14px;border-top:1px solid var(--color-border-secondary);color:var(--color-text-secondary)}
.arow:first-child{border-top:0}
.arow.dg{color:var(--color-text-error-primary)}
.shp{margin:0;padding:0 16px 12px;color:var(--color-text-tertiary);font-size:14px}
.shf.two{display:flex;gap:8px}
.cta.sec{background:var(--color-bg-primary)!important;color:var(--color-text-primary)!important;border:1px solid var(--color-border-primary)!important}
.dgrid{display:grid;grid-template-columns:360px 1fr;gap:16px;align-items:start}
.dgrid .card{display:flex;flex-direction:column;gap:12px}
.mono.il-font-size-24{font-size:24px}
